"""Independent reference optimality check using exact lexicographic pairs."""
from functools import lru_cache
import math

WIDTH=(16,8,4); LANES=(4,8,16)

def lexmin(a,b):
    if a is None: return b
    if b is None: return a
    return a if (a[0],a[1])<(b[0],b[1]) else b

def plus(a,b):
    return (a[0]+b[0], a[1]+b[1])

def reference(versions, qtables, ttables, costs, budget):
    """versions: list of (starts,hops); qtables/ttables per version; costs (hit,miss,dec)"""
    hit,miss,dec=costs
    phis=[]
    for starts,q,t in zip(versions,qtables,ttables):
        R=len(starts)
        spread=[[ (starts[j-1]-starts[i]) for j in range(i+1,R+1)] for i in range(R)]
        memo={}
        def legal(i,j,mode):
            sp=starts[j-1]-starts[i]
            if mode==1: return sp < (1<<64)
            if mode==2: return sp < (1<<32)
            return True
        def opts(i,j):
            L=j-i; out=[]
            for mode in range(3):
                if not legal(i,j,mode): continue
                if L<=8:
                    K=L; P=(32+K*WIDTH[mode]+63)//64
                    out.append((0,mode,P,(K+LANES[mode]-1)//LANES[mode]+dec[mode]))
                for b in range(2,min(9,L)+1):
                    K=b-1; P=(32+4*b+K*WIDTH[mode]+63)//64
                    out.append((b,mode,P,(K+LANES[mode]-1)//LANES[mode]+dec[mode]))
            return out
        def solve(i,j,c):
            key=(i,j,c)
            if key in memo: return memo[key]
            best=None
            for b,mode,P,coeff in opts(i,j):
                L=j-i
                if b and b>L: continue
                for cached in (0,1):
                    used = P if cached else 0
                    if used>c: continue
                    work = P*(hit if cached else miss)*t[i][j] + coeff*q[i][j]
                    pages = P
                    if b==0:
                        sub=(0,0)
                    else:
                        sub=partition(i,j,b,c-used)
                        if sub is None: continue
                    cand=(work+sub[0], pages+sub[1])
                    best=lexmin(best,cand)
            memo[key]=best
            return best
        pmemo={}
        def partition(i,j,b,c):
            key=(i,j,b,c)
            if key in pmemo: return pmemo[key]
            best=None
            if b==1:
                best=solve(i,j,c)
            else:
                for k in range(i+b-1, j):
                    for c1 in range(c+1):
                        a=partition(i,k,b-1,c1)
                        if a is None: continue
                        d=solve(k,j,c-c1)
                        if d is None: continue
                        best=lexmin(best, plus(a,d))
            pmemo[key]=best
            return best
        val=solve(0,R,min(budget, 4*(2*R-1)))
        # phi for every budget
        phi=[solve(0,R,c) for c in range(budget+1)]
        phis.append([(w, p + 1 + (4*R+63)//64) for (w,p) in phi])
    # cross-version allocation: lexicographic on summed pairs
    dmemo={}
    def alloc(v, cap):
        if v==len(phis): return (0,0)
        key=(v,cap)
        if key in dmemo: return dmemo[key]
        best=None
        for c in range(cap+1):
            a=phis[v][c]
            if a is None: continue
            b=alloc(v+1, cap-c)
            if b is None: continue
            best=lexmin(best, plus(a,b))
        dmemo[key]=best
        return best
    return alloc(0,budget)
